// End-to-end tests on real PDFs: the demo files generated by
// scripts/make-samples.mjs (public/samples) and a LibreOffice pair.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { openPdf } from '../src/node/pdf.ts';
import { renderPage, canRender } from '../src/node/render.ts';
import { extractText } from '../src/pdf/extract.ts';
import { buildDocModel } from '../src/core/tokenize.ts';
import { compareDocs } from '../src/core/compare.ts';
import { addVisualChanges } from '../src/core/pipeline.ts';
import { buildJson, buildReport } from '../src/core/report.ts';
import { describeChange } from '../src/core/describe.ts';
import type { Change } from '../src/core/types.ts';

const dir = new URL('./fixtures/', import.meta.url).pathname;
const samples = new URL('../public/samples/', import.meta.url).pathname;

async function run(name: string, visual: boolean) {
  const pa = await openPdf(samples + `${name}-before.pdf`);
  const pb = await openPdf(samples + `${name}-after.pdf`);
  const r = compareDocs(buildDocModel(await extractText(pa, 'before')), buildDocModel(await extractText(pb, 'after')));
  if (visual) await addVisualChanges(r, (p) => renderPage(pa, p, 1.5), (p) => renderPage(pb, p, 1.5));
  return r;
}

const pages = (c: Change) => `${c.old.pages.map((p) => p + 1).join(',')}→${c.new.pages.map((p) => p + 1).join(',')}`;

for (const name of ['proposal', 'proposal-zh']) {
  test(`${name}: text changes survive re-pagination`, async () => {
    const r = await run(name, false);
    assert.equal(r.oldDoc.pages.length, 8);
    assert.equal(r.newDoc.pages.length, 9);
    // One paragraph inserted on page 2 pushes everything after it down a page.
    assert.deepEqual(r.oldToNew, [0, 1, 3, 4, 5, 6, 7, 8]);
    const text = r.changes.filter((c) => c.category === 'text');
    const price = text.find((c) => c.numeric?.from === '8,000');
    assert.ok(price, 'price change found');
    assert.equal(price.numeric!.to, '9,500');
    assert.equal(pages(price), '3→4');
    const deleted = text.find((c) => c.kind === 'delete');
    assert.ok(deleted && deleted.wholeParagraphs === 1, 'deleted paragraph');
    assert.equal(pages(deleted), '6→7');
    assert.ok(text.some((c) => c.kind === 'insert' && c.wholeParagraphs === 1 && pages(c) === '2→2'));
    assert.ok(text.some((c) => c.kind === 'move' && pages(c) === '5→6'));
    const overflow = r.changes.find((c) => c.kind === 'overflow');
    assert.ok(overflow && overflow.overflow?.edge === 'right' && pages(overflow) === '→9', 'table overflow on page 9');
    // Nothing else: headers, footers and page numbers are ignored.
    assert.ok(text.length <= 9, text.map((c) => describeChange('en', c)).join('\n'));
  });

  test(`${name}: visual changes`, { skip: !(await canRender()) && 'no canvas' }, async () => {
    const r = await run(name, true);
    const graphic = r.changes.filter((c) => c.kind === 'graphic');
    // The Gantt chart (old p4 → new p5), the red text (p7 → p8) and the rate table (p8 → p9).
    assert.ok(graphic.some((c) => pages(c) === '4→5' && !c.format), 'chart change');
    assert.ok(graphic.some((c) => pages(c) === '7→8' && c.format?.appearanceChanged), 'colour change');
    assert.ok(graphic.some((c) => pages(c) === '8→9'), 'table change');
    assert.equal(graphic.length, 3, graphic.map(pages).join(' '));
  });
}

test('report and JSON export', async () => {
  const r = await run('proposal', false);
  const html = buildReport({ result: r, lang: 'en', oldName: 'a <b>.pdf', newName: 'b.pdf', reviews: { c1: { status: 'question', note: 'Check <this>' } } });
  assert.ok(html.startsWith('<!doctype html>'));
  assert.ok(html.includes('a &lt;b&gt;.pdf'));
  assert.ok(html.includes('Check &lt;this&gt;'));
  assert.ok(html.includes('Number changed: 8,000 → 9,500'));
  assert.ok(!/<script/i.test(html), 'report contains no scripts');
  const json = buildJson({ result: r, lang: 'zh', oldName: 'a', newName: 'b' }) as { changes: { description: string }[] };
  assert.ok(json.changes.some((c) => c.description.includes('数字变化：8,000 → 9,500')));
});

// A LibreOffice-produced pair with justified text: the fee sentence moved up
// one paragraph (and its amount changed), one paragraph was inserted and one
// deleted, and one word was replaced.
test('LibreOffice: moves, numbers and whole paragraphs', async () => {
  const pa = await openPdf(dir + 'agreement-before.pdf');
  const pb = await openPdf(dir + 'agreement-after.pdf');
  const a = buildDocModel(await extractText(pa, 'a'));
  const b = buildDocModel(await extractText(pb, 'b'));
  const expected = ['Changed “contractor” → “supplier”', 'Added a paragraph', 'Number changed: 11,900 → 12,400 (+4.2%)', 'Moved a paragraph', 'Deleted a paragraph'];
  assert.deepEqual(compareDocs(a, b).changes.map((c) => describeChange('en', c)), expected);
  // Fewer distinct keys (case-folded) must not fragment the moved paragraph.
  assert.deepEqual(compareDocs(a, b, { ignoreCase: true }).changes.map((c) => describeChange('en', c)), expected);
});

// A chart-only page after an inserted page cannot be paired from text. It
// is the only page without text between two paired pages on both sides, so
// it is paired with its counterpart automatically; a manual pair gives the
// same result (scripts/make-pairing-fixture.mjs).
test('manual page pairing finds a change on a page without text', { skip: !(await canRender()) && 'no canvas' }, async () => {
  const pa = await openPdf(dir + 'textless-before.pdf');
  const pb = await openPdf(dir + 'textless-after.pdf');
  const a = buildDocModel(await extractText(pa, 'a'));
  const b = buildDocModel(await extractText(pb, 'b'));
  const run = async (manualPairs: [number, number][]) => {
    const r = compareDocs(a, b, { manualPairs });
    await addVisualChanges(r, (p) => renderPage(pa, p, 1.5), (p) => renderPage(pb, p, 1.5));
    return r;
  };
  const auto = await run([]);
  assert.deepEqual(auto.coverage.old.textless, [1]);
  const ga = auto.changes.filter((c) => c.kind === 'graphic');
  assert.equal(ga.length, 1, 'the chart pages are paired without help');
  assert.equal(pages(ga[0]), '2→3');
  const paired = await run([[1, 2]]);
  const g = paired.changes.filter((c) => c.kind === 'graphic');
  assert.equal(g.length, 1);
  assert.equal(pages(g[0]), '2→3');
  assert.ok(paired.pageLinks.some((l) => l.manual && l.oldPage === 1 && l.newPage === 2));
  // Scrolling anchors include the pair's page tops.
  assert.ok(paired.anchors.some((x) => x.oldPage === 1 && x.newPage === 2 && x.oldY === 0));
  // Out-of-range pairs are ignored.
  assert.equal(compareDocs(a, b, { manualPairs: [[9, 9]] }).pageLinks.filter((l) => l.manual).length, 0);
});
